-- ALTER VIEW SET/UNSET and governance policy actions
-- https://docs.snowflake.com/en/sql-reference/sql/alter-view

ALTER VIEW v1 SET COMMENT = 'x';

ALTER VIEW IF EXISTS v1 SET COMMENT = 'x';

ALTER VIEW v1 SET CHANGE_TRACKING = TRUE;

ALTER VIEW v1 SET CHANGE_TRACKING = FALSE;

ALTER VIEW v1 SET SECURE CHANGE_TRACKING = TRUE COMMENT = 'several properties';

ALTER VIEW v1 SET CONTACT STEWARD = my_contact;

ALTER VIEW v1 SET CONTACT STEWARD = my_contact, SUPPORT = support_contact;

ALTER VIEW v1 UNSET CONTACT STEWARD;

ALTER VIEW v1 UNSET DCM PROJECT;

ALTER VIEW v1 DROP ALL ROW ACCESS POLICIES;

ALTER VIEW v1 SET AGGREGATION POLICY ap1;

ALTER VIEW v1 SET AGGREGATION POLICY ap1 ENTITY KEY (c1, c2) FORCE;

ALTER VIEW v1 UNSET AGGREGATION POLICY;

ALTER VIEW v1 SET JOIN POLICY jp1;

ALTER VIEW v1 SET JOIN POLICY jp1 FORCE;

ALTER VIEW v1 UNSET JOIN POLICY;

ALTER VIEW v1 MODIFY COLUMN c1 SET PROJECTION POLICY pp1;

ALTER VIEW v1 ALTER COLUMN c1 SET PROJECTION POLICY my_db.my_schema.pp1 FORCE;

ALTER VIEW v1 MODIFY COLUMN c1 UNSET PROJECTION POLICY;
